/bin/zsh -lc "python3 tools/verify.py && python3 -m unittest -v && python3 - <<'PY'
from signalnest import UnknownRoute, resolve_route

assert resolve_route(\"email\") == \"standard\"
assert resolve_route(\"SMS\") == \"mobile\"
for value in (None, 1, b\"pager\"):
    try:
        resolve_route(value)
    except TypeError:
        pass
    else:
        raise AssertionError(f\"expected TypeError for {value"'!r}")
try:
    resolve_route("carrier-pigeon")
except UnknownRoute:
    pass
else:
    raise AssertionError("expected UnknownRoute")
PY'

